<script setup lang="ts">import{useI18n}from'vue-i18n';import AccountShell from'../components/AccountShell.vue';const{t,tm}=useI18n();const rows=[{id:'BB-20260808-001',box:'pokemon-starlight',type:'single',cost:'500',status:'completed',time:'2026-08-08 14:32'},{id:'BB-20260805-028',box:'eevee-evolution',type:'ten',cost:'4,500',status:'completed',time:'2026-08-05 20:18'},{id:'BB-20260802-116',box:'mewtwo-genesis',type:'single',cost:'600',status:'processing',time:'2026-08-02 09:44'}];const headers=()=>tm('orders.headers') as string[]</script>
<template><AccountShell><div class="title"><div><span class="eyebrow">{{t('eyebrow.orders')}}</span><h1>{{t('orders.title')}}</h1><p>{{t('orders.subtitle')}}</p></div><RouterLink to="/blind-boxes" class="btn btn-primary">{{t('orders.newBox')}}</RouterLink></div><div class="balance card"><div><span>{{t('orders.balance')}}</span><b>12,450</b></div><RouterLink to="/recharge" class="btn btn-primary">{{t('orders.recharge')}}</RouterLink><RouterLink to="/account/transactions" class="btn btn-outline">{{t('orders.transactions')}}</RouterLink></div><section class="card orders"><div class="filters"><select><option>{{t('orders.allStatus')}}</option><option>{{t('orders.completed')}}</option><option>{{t('orders.processing')}}</option></select><select><option>{{t('orders.allTypes')}}</option><option>{{t('orders.single')}}</option><option>{{t('orders.ten')}}</option></select><input :placeholder="t('orders.searchPlaceholder')"><button class="btn btn-dark">{{t('common.search')}}</button></div><div class="table-wrap"><table class="table"><thead><tr><th v-for="header in headers()" :key="header">{{header}}</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td :data-label="headers()[0]"><b>{{row.id}}</b></td><td :data-label="headers()[1]">{{t(`boxes.${row.box}.name`)}}<small>{{t('orders.batch')}}</small></td><td :data-label="headers()[2]">{{t(`orders.${row.type}`)}}</td><td :data-label="headers()[3]">{{row.cost}}</td><td :data-label="headers()[4]">{{row.time}}</td><td :data-label="headers()[5]"><span :class="['pill',row.status==='completed'?'green':'gold']">{{t(`orders.${row.status}`)}}</span></td><td :data-label="headers()[6]"><button class="link">{{t('orders.view')}}</button></td></tr></tbody></table></div></section></AccountShell></template>
